package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;

public final class ReadingControlsChecks extends DeviceChecks {
 static final String BOOK="6982529841564224526";
 void baseline()throws Exception{
  launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",BOOK).putExtra("chapter_index",0).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();
  ui(()->{reader.settings.comments=true;reader.settings.save();reader.comments.retry();});
  waitFor(()->reader.layouts.containsKey(1),30,"next chapter layout");
  waitFor(()->!reader.commentCounts(reader.chapterId(1)).isEmpty()&&reader.layouts.containsKey(1)&&!reader.layouts.get(1).commentParagraphs.isEmpty(),25,"prefetched next chapter counts before entering");
  assertTrue(!reader.layouts.get(1).commentParagraphs.isEmpty(),"next chapter first layout includes bubbles");
  record("next_chapter_bubbles_before_entry",true);
 }

 void cacheAndMigration()throws Exception{
  Context c=new TestContext(getTargetContext());SharedPreferences prefs=c.getSharedPreferences("ReaderActivity",0);
  for(int old=0;old<3;old++){prefs.edit().clear().putBoolean("reader_v2",true).putInt("spacing",old).commit();ReaderSettings setting=new ReaderSettings(c);assertTrue(setting.lineSpacing==ReaderSettings.legacySpacing(old),"legacy spacing "+old);assertTrue(setting.volumeKeys,"volume enabled by default");setting.save();assertTrue(new ReaderSettings(c).lineSpacing==setting.lineSpacing,"migration persisted");}
  record("three_legacy_spacing_values_preserved",true);
  LocalLibrary db=new LocalLibrary(c);ParagraphCommentApi api=new ParagraphCommentApi(c,db,(url,headers,body)->{throw new AssertionError("cache read used network");});
  JSONObject body=new JSONObject().put("id","fixture").put("text","匹配正文").put("item_version","v1").put("paragraph_meta",new JSONArray().put(new JSONObject().put("id","1").put("start",0)));
  String mapping=ParagraphCommentApi.key("mapping","book","fixture","","",""),stats=ParagraphCommentApi.key("stats","book","fixture","v1","","");
  api.cache.put(mapping,body);api.cache.put(stats,new JSONObject().put("1",5));
  assertTrue(ParagraphSnapshot.cached(api,"book",body).counts.get(0)==5,"cache counts");api.cache.getWritableDatabase().execSQL("UPDATE cache SET updated=1");
  assertTrue(ParagraphSnapshot.cached(api,"book",body).counts.get(0)==5,"expired cache still displays");
  assertTrue(ParagraphSnapshot.cached(api,"book",new JSONObject(body.toString()).put("text","另一个正文"))==null,"wrong text rejected");
  assertTrue(ParagraphSnapshot.cached(api,"another-book",body)==null,"book isolation");api.cache.put(mapping,new JSONObject(body.toString()).put("item_version","v2"));assertTrue(ParagraphSnapshot.cached(api,"book",body)==null,"version isolation");
  assertTrue(ParagraphComments.commentTime(0).isEmpty()&&ParagraphComments.commentTime(-1).isEmpty()&&ParagraphComments.commentTime(Long.MAX_VALUE).isEmpty(),"invalid time hidden");
  java.util.TimeZone oldZone=java.util.TimeZone.getDefault();try{java.util.TimeZone.setDefault(java.util.TimeZone.getTimeZone("Asia/Shanghai"));assertTrue(ParagraphComments.commentTime(1704067200L).equals("2024-01-01 08:00"),"seconds and local timezone");}finally{java.util.TimeZone.setDefault(oldZone);}
  api.cache.close();db.close();record("cached_offline_stale_version_body_and_time_guards",true);
 }
 void key(int code){sendKeySync(new KeyEvent(KeyEvent.ACTION_DOWN,code));sendKeySync(new KeyEvent(KeyEvent.ACTION_UP,code));}
 void page(int p){ui(()->{ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,reader.index,f.totalChapters,f.layout,p));});}
 void turns()throws Exception{
  waitFor(()->reader.hasWindowFocus(),5,"reader focus");ui(()->{reader.settings.volumeKeys=true;reader.settings.save();reader.hideOverlays();});
  for(PageTurnMode mode:PageTurnMode.values()){
   ui(()->{reader.settings.pageTurnMode=mode;reader.settings.save();reader.surface.modeChanged();});page(1);key(KeyEvent.KEYCODE_VOLUME_UP);if(mode==PageTurnMode.SIMULATION)ui(()->reader.neighborCommentsChanged(reader.chapterId(1)));waitFor(()->!reader.surface.animating()&&reader.surface.frame.pageIndex==2,5,"volume plus next "+mode);key(KeyEvent.KEYCODE_VOLUME_DOWN);waitFor(()->!reader.surface.animating()&&reader.surface.frame.pageIndex==1,5,"volume minus previous "+mode);
  }record("volume_both_directions_all_four_modes",true);
  long now=SystemClock.uptimeMillis();sendKeySync(new KeyEvent(now,now,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_VOLUME_UP,0));waitFor(()->!reader.surface.animating(),4,"initial held key");int once=reader.surface.frame.pageIndex;
  for(int n=1;n<6;n++)sendKeySync(new KeyEvent(now,SystemClock.uptimeMillis(),KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_VOLUME_UP,n));sendKeySync(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_VOLUME_UP));SystemClock.sleep(350);assertTrue(reader.surface.frame.pageIndex==once,"held key flips once");
  ui(()->reader.busy=true);key(KeyEvent.KEYCODE_VOLUME_UP);ui(()->reader.busy=false);assertTrue(reader.surface.frame.pageIndex==once,"busy key not queued");record("volume_repeat_and_busy_guards",true);
  ui(()->reader.showSettings());assertTrue(!reader.volumeReading(),"settings uses volume");key(KeyEvent.KEYCODE_VOLUME_UP);assertTrue(reader.surface.frame.pageIndex==once,"settings does not flip");SystemClock.sleep(3500);shot("settings-controls");
  Switch toggle=(Switch)findDescription(reader.panel,"音量键翻页：加号下一页，减号上一页");assertTrue(toggle!=null,"volume switch");ui(()->toggle.setChecked(false));assertTrue(!new ReaderSettings(getTargetContext()).volumeKeys,"volume choice saved");ui(()->reader.hideOverlays());key(KeyEvent.KEYCODE_VOLUME_DOWN);assertTrue(reader.surface.frame.pageIndex==once,"disabled no flip");ui(()->{reader.settings.volumeKeys=true;reader.settings.save();});record("volume_settings_toggle_and_system_fallback",true);
  ui(()->reader.open(0,0));ready();waitFor(()->reader.layouts.containsKey(1)&&!reader.layouts.get(1).commentParagraphs.isEmpty(),30,"warm target with bubbles");
  page(reader.surface.frame.layout.pages.size()-1);key(KeyEvent.KEYCODE_VOLUME_UP);waitFor(()->!reader.surface.animating()&&reader.index==1,8,"volume crosses forward");assertTrue(!reader.surface.frame.layout.commentParagraphs.isEmpty(),"first entered frame contains comment bubbles");assertTrue(reader.comments.metadata!=null,"cached target mapping available immediately");shot("prefetched-chapter-first-page");
  key(KeyEvent.KEYCODE_VOLUME_DOWN);waitFor(()->!reader.surface.animating()&&reader.index==0,8,"volume crosses backward");record("volume_cross_chapter_and_first_frame_bubbles",true);
 }
 @Override void coverage(ReaderPaginator p){int end=0;for(ReaderPaginator.Page page:p.pages){assertTrue(page.start==end&&page.end>=page.start,"contiguous page");end=page.end;for(ReaderPaginator.Fragment f:page.fragments){assertTrue(f.firstLine<f.lastLine&&f.y>=p.top-1,"valid fragment");float baseline=f.y-f.layout.getLineTop(f.firstLine)+f.layout.getLineBaseline(f.lastLine-1);assertTrue(baseline+f.layout.paint.getFontMetrics().descent<=p.bottom+1,"glyph descenders fit page");android.graphics.RectF bubble=p.commentBubble(f);if(bubble!=null)assertTrue(bubble.bottom<=p.bottom+1,"comment bubble fits page");}if(end<p.text.length()&&end>0)assertTrue(!(Character.isHighSurrogate(p.text.charAt(end-1))&&Character.isLowSurrogate(p.text.charAt(end))),"no split surrogate");}assertTrue(end==p.text.length(),"complete text coverage");}
 void spacing()throws Exception{
  SystemClock.sleep(3500);page(1);int anchor=reader.anchor;float previous=-1;
  for(int value:new int[]{0,25,50,75,100}){ui(()->reader.applyLineSpacing(value));ready();assertTrue(reader.anchor==anchor,"spacing anchor "+value);coverage(reader.surface.frame.layout);assertTrue(reader.surface.frame.layout.lineSpace>previous,"actual line gap increases "+value);previous=reader.surface.frame.layout.lineSpace;assertTrue(new ReaderSettings(getTargetContext()).spacingPercent==value,"spacing persisted "+value);}
  ui(()->reader.showSettings());View slider=findDescription(reader.panel,"文字行间距：100");assertTrue(slider instanceof SeekBar,"spacing slider exists");int[] loc=new int[2];ui(()->slider.getLocationOnScreen(loc));record("slider_swipe_ready",Math.round(loc[0]+slider.getWidth()*.85f)+" "+Math.round(loc[1]+slider.getHeight()*.5f)+" "+Math.round(loc[0]+slider.getWidth()*.35f)+" "+Math.round(loc[1]+slider.getHeight()*.5f));waitFor(()->reader.settings.spacingPercent!=100,60,"external OS slider swipe");ready();assertTrue(reader.settings.spacingPercent>0&&reader.settings.spacingPercent<100,"drag selects intermediate spacing");assertTrue(reader.anchor==anchor,"drag preserves anchor");shot("spacing-slider");ui(()->reader.hideOverlays());
  int saved=reader.settings.spacingPercent;ActivityMonitor monitor=addMonitor(ReaderActivity.class.getName(),null,false);ui(()->reader.recreate());ReaderActivity next=(ReaderActivity)monitor.waitForActivityWithTimeout(10000);removeMonitor(monitor);assertTrue(next!=null,"reader recreated");reader=next;ready();assertTrue(reader.settings.spacingPercent==saved&&reader.anchor==anchor,"recreate restores spacing and offset");record("spacing_geometry_drag_persistence_anchor",saved);
 }
 void timeAndWarm()throws Exception{
  ui(()->reader.open(0,0));ready();waitFor(()->reader.comments.metadata!=null&&!reader.comments.counts.isEmpty(),30,"current mapping");
  ParagraphCommentApi client=reader.comments.api;String id=reader.chapterId(0),version=reader.comments.version;JSONObject para=reader.comments.metadata.getJSONArray("paragraph_meta").getJSONObject(0);
  JSONObject raw=client.request("/novel/commentapi/comment/list/"+id+"/v1",new JSONObject().put("business_param",new JSONObject().put("book_id",BOOK).put("item_version",version).put("para_index",Integer.parseInt(para.getString("id")))).put("chapter_id",id).put("comment_source",2).put("comment_type",1).put("count",20).put("group_type",15).put("sort",0));
  Map<String,Long> times=new HashMap<>();JSONArray entries=raw.getJSONArray("data_list");for(int i=0;i<entries.length();i++){JSONObject item=entries.getJSONObject(i).getJSONObject("comment");times.put(item.getString("comment_id"),item.getJSONObject("common").optLong("create_timestamp"));}
  JSONObject page=client.comments(BOOK,id,version,para.getString("id"),"",para.getString("text"));int compared=0;for(int i=0;i<page.getJSONArray("items").length();i++){JSONObject item=page.getJSONArray("items").getJSONObject(i);Long expected=times.get(item.optString("id"));if(expected!=null){assertTrue(expected==item.optLong("create_timestamp")&&expected>0,"live timestamp retained");compared++;}}assertTrue(compared>0,"live time comparison");record("real_api_timestamps_match",compared);
  String key=ParagraphCommentApi.key("page",BOOK,id,version,para.getString("id"),"");JSONObject legacy=new JSONObject(page.toString());legacy.remove("schema");for(int i=0;i<legacy.getJSONArray("items").length();i++)legacy.getJSONArray("items").getJSONObject(i).remove("create_timestamp");client.cache.put(key,legacy);
  ui(()->reader.comments.open(para.optInt("start")));waitFor(()->!reader.comments.loading&&!reader.comments.displayed.isEmpty()&&reader.comments.displayed.get(0).optLong("create_timestamp")>0,30,"legacy page refreshed with time");
  String label="评论时间："+ParagraphComments.commentTime(reader.comments.displayed.get(0).optLong("create_timestamp"));assertTrue(findDescription(reader.comments.panel,label)!=null,"time rendered in comment");assertTrue(!reader.volumeReading(),"comment sheet uses system volume");int anchor=reader.anchor;key(KeyEvent.KEYCODE_VOLUME_UP);assertTrue(reader.anchor==anchor,"comment sheet no page turn");shot("comments-time-day");
  ui(()->{reader.comments.dismiss();reader.settings.night=true;reader.settings.save();reader.comments.open(para.optInt("start"));});waitFor(()->!reader.comments.loading&&!reader.comments.displayed.isEmpty(),15,"night comments");shot("comments-time-night");ui(()->{reader.comments.dismiss();reader.settings.night=false;reader.settings.save();});record("legacy_time_refresh_and_day_night_rows",true);
  waitFor(()->{for(int n=1;n<=5;n++)if(reader.comments.snapshots.get(reader.chapterId(n))==null)return false;return true;},90,"all five chapters warmed");record("next_five_mappings_and_counts_warmed",true);
  ui(()->{reader.open(2,0);reader.open(4,0);reader.open(1,0);});ready();waitFor(()->reader.comments.metadata!=null&&reader.comments.chapterId.equals(reader.chapterId(1)),15,"rapid jump mapping");assertTrue(reader.comments.metadata.optString("id").equals(reader.chapterId(1)),"old callbacks do not replace target");record("rapid_chapter_switch_mapping_isolation",true);
  ui(()->{reader.settings.comments=false;reader.comments.retry();reader.settingChanged();});ready();assertTrue(reader.comments.warmWindow.isEmpty()&&reader.comments.warmer.getQueue().isEmpty(),"disabled cancels warming");record("disabled_comments_stop_prefetch",true);
 }
 void spacingRange()throws Exception{tightSpacing();}
 void tightSpacing()throws Exception{
  baseline();ui(()->{reader.settings.font=24;reader.settings.fontWeight=0;reader.settings.serif=false;reader.settings.save();reader.open(0,0);});ready();int anchor=reader.anchor;
  for(int amount:new int[]{0,50,100}){ui(()->reader.applyLineSpacing(amount));ready();assertTrue(reader.anchor==anchor,"tight spacing anchor");shot("tight-spacing-"+amount);record("tight_spacing_"+amount,new JSONObject().put("lineGapPx",reader.surface.frame.layout.lineSpace).put("paragraphGapPx",reader.surface.frame.layout.paragraphGap));}
  int rasterCases=0;for(boolean serif:new boolean[]{false,true})for(int weight:new int[]{0,100}){
   ReaderSettings setting=new ReaderSettings(getTargetContext());setting.serif=serif;setting.fontWeight=weight;setting.font=24;android.text.TextPaint ink=ReaderPaginator.bodyPaint(setting,3);ink.setAntiAlias(true);ink.setColor(android.graphics.Color.BLACK);
   ReaderTextLayout layout=new ReaderTextLayout(repeat("国田",60),ink,720,0,false,0,true,0);
   android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(720,layout.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(bitmap);canvas.drawColor(android.graphics.Color.WHITE);layout.draw(canvas);
   int previous=-1,gap=0,min=999,max=0;boolean inBand=false;
   for(int y=0;y<bitmap.getHeight();y++){boolean dark=false;for(int x=0;x<720;x++)if(android.graphics.Color.red(bitmap.getPixel(x,y))<128){dark=true;break;}if(dark){if(!inBand&&previous>=0){gap=y-previous-1;min=Math.min(min,gap);max=Math.max(max,gap);}previous=y;inBand=true;}else inBand=false;}
   bitmap.recycle();assertTrue(min>=0&&max<=3,"rendered near-zero line gap "+serif+"/"+weight+"="+min+".."+max);record("raster_gap_"+serif+"_"+weight,min+".."+max);rasterCases++;
  }record("pixel_render_checks",rasterCases);
  int cases=0;for(boolean serif:new boolean[]{false,true})for(int weight:new int[]{0,100})for(int font:new int[]{16,24,30})for(int amount:new int[]{0,50,100}){
   ReaderSettings setting=new ReaderSettings(getTargetContext());setting.serif=serif;setting.fontWeight=weight;setting.font=font;setting.legacyLineSpacing=false;setting.spacingPercent=amount;
   String para=repeat("国田目回田国",12);String sample=para+"\n\n"+para+"\n\n中文 English gy ÁÉj café 🙂，。《》";
   Map<Integer,Long> bubbles=new HashMap<>();bubbles.put(para.length()+2,5L);
   ReaderPaginator paginator=new ReaderPaginator(sample,"标题保持原状",1080,1920,3,3,setting,bubbles);int covered=0;float stroke=paginator.paint.getStyle()==android.graphics.Paint.Style.FILL?0:paginator.paint.getStrokeWidth()/2;
   android.text.TextPaint fill=new android.text.TextPaint(paginator.paint);fill.setStyle(android.graphics.Paint.Style.FILL);float previousBottom=Float.NaN;
   for(ReaderPaginator.Page page:paginator.pages){assertTrue(page.start==covered,"tight contiguous");covered=page.end;previousBottom=Float.NaN;
    for(ReaderPaginator.Fragment fragment:page.fragments){for(int i=fragment.firstLine;i<fragment.lastLine;i++){ReaderTextLayout.Line line=fragment.layout.lines.get(i);android.graphics.Rect bounds=new android.graphics.Rect();fill.getTextBounds(fragment.layout.text,line.start,line.end,bounds);float baseline=fragment.y-fragment.layout.getLineTop(fragment.firstLine)+line.baseline,top=baseline+bounds.top-stroke,bottom=baseline+bounds.bottom+stroke;
     assertTrue(top>=paginator.top-.01&&bottom<=paginator.bottom+.01,"ink within page");if(!Float.isNaN(previousBottom)){assertTrue(top-previousBottom>=.99f,"ink never overlaps across lines and paragraphs");if(amount==0&&fragment.paragraphStart==0)assertTrue(top-previousBottom<=1.01f,"zero CJK gap exactly one physical pixel");}previousBottom=bottom;
    }android.graphics.RectF bubble=paginator.commentBubble(fragment);if(bubble!=null){assertTrue(bubble.top>=fragment.y&&bubble.bottom<=paginator.bottom,"bubble fits line/page");previousBottom=Math.max(previousBottom,bubble.bottom);}}
   }assertTrue(covered==sample.length(),"tight text complete");if(amount==0)assertTrue(paginator.paragraphGap==0,"no paragraph extra gap");cases++;
  }record("tight_geometry_fonts_weights_sizes_levels",cases);
  ui(()->{reader.applyLineSpacing(0);reader.showSettings();});ready();assertTrue(findDescription(reader.panel,"文字行间距：0") instanceof SeekBar,"zero to hundred slider");shot("tight-spacing-settings");ui(()->reader.hideOverlays());
  int savedAnchor=reader.anchor;ActivityMonitor monitor=addMonitor(ReaderActivity.class.getName(),null,false);ui(()->reader.recreate());ReaderActivity next=(ReaderActivity)monitor.waitForActivityWithTimeout(10000);removeMonitor(monitor);assertTrue(next!=null,"recreated");reader=next;ready();assertTrue(!reader.settings.legacyLineSpacing&&reader.settings.spacingPercent==0&&reader.anchor==savedAnchor,"zero setting and anchor persisted");record("tight_spacing_restart_and_anchor",true);
 }
 JSONObject commentFixture(String id,long timestamp,String image)throws Exception{return new JSONObject().put("id",id).put("create_timestamp",timestamp).put("text","comment "+id).put("images",new JSONArray().put(new JSONObject().put("url",image)));}
 JSONObject commentPage(JSONObject... items)throws Exception{JSONArray list=new JSONArray();for(JSONObject item:items)list.put(item);return new JSONObject().put("items",list).put("cursor","next").put("more",true);}
 void reviewFixes()throws Exception{
  baseline();ParagraphComments comments=new ParagraphComments(reader);
  try{comments.adapter=new BaseAdapter(){public int getCount(){return comments.displayed.size();}public Object getItem(int p){return comments.displayed.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,android.view.ViewGroup parent){return null;}};
   JSONObject first=commentPage(commentFixture("first",10,"first-image")),cached=commentPage(commentFixture("second",0,"old-image")),fresh=commentPage(commentFixture("second",1704067200L,"new-image"),commentFixture("third",20,"third-image"));
   ui(()->{comments.apply(first,"",true);comments.apply(cached,"page2",true);comments.apply(fresh,"page2",false);});
   assertTrue(comments.displayed.size()==3,"refresh does not duplicate rows");assertTrue(comments.displayed.get(0).optString("id").equals("first")&&comments.displayed.get(1).optString("id").equals("second"),"refresh preserves row order");assertTrue(comments.displayed.get(1).optLong("create_timestamp")==1704067200L,"second page cached comment gains timestamp immediately");record("second_page_timestamp_refresh",true);
   assertTrue(comments.imageUrls.equals(Arrays.asList("first-image","new-image","third-image")),"image references refreshed without stale images");
   ui(()->comments.apply(fresh,"page2",false));assertTrue(comments.displayed.size()==3&&comments.imageUrls.size()==3,"repeated response idempotent");record("refresh_order_images_and_deduplication",true);
   ui(()->comments.apply(first,"",false));assertTrue(comments.displayed.size()==1&&comments.imageUrls.equals(Arrays.asList("first-image")),"first page still replaces list");record("first_page_reset",true);
  }finally{comments.close();}
 }
 Map<String,?> originalPrefs;List<ContentValues> progress=new ArrayList<>(),books=new ArrayList<>();LocalLibrary savedDb;
 void preserve(){originalPrefs=new HashMap<>(getTargetContext().getSharedPreferences("ReaderActivity",0).getAll());savedDb=new LocalLibrary(getTargetContext());snapshotTable("progress",progress);snapshotTable("books",books);}
 void snapshotTable(String table,List<ContentValues> rows){try(android.database.Cursor c=savedDb.getReadableDatabase().rawQuery("SELECT * FROM "+table,null)){while(c.moveToNext()){ContentValues value=new ContentValues();android.database.DatabaseUtils.cursorRowToContentValues(c,value);rows.add(value);}}}
 void restore(){if(reader!=null)ui(()->reader.finish());if(main!=null)ui(()->main.finish());if(savedDb!=null){android.database.sqlite.SQLiteDatabase db=savedDb.getWritableDatabase();db.beginTransaction();try{db.delete("progress",null,null);for(ContentValues value:progress)db.insertOrThrow("progress",null,value);for(ContentValues book:books){ContentValues value=new ContentValues();value.put("last_read",book.getAsLong("last_read"));db.update("books",value,"id=?",new String[]{book.getAsString("id")});}db.setTransactionSuccessful();}finally{db.endTransaction();savedDb.close();}}if(originalPrefs!=null){SharedPreferences.Editor edit=getTargetContext().getSharedPreferences("ReaderActivity",0).edit().clear();for(Map.Entry<String,?> entry:originalPrefs.entrySet()){Object value=entry.getValue();String k=entry.getKey();if(value instanceof Boolean)edit.putBoolean(k,(Boolean)value);else if(value instanceof Integer)edit.putInt(k,(Integer)value);else if(value instanceof Long)edit.putLong(k,(Long)value);else if(value instanceof Float)edit.putFloat(k,(Float)value);else if(value instanceof String)edit.putString(k,(String)value);}edit.commit();}}
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"reading-controls");output.mkdirs();Bundle result=new Bundle();Throwable failure=null;try{preserve();if("review-fixes".equals(args.getString("phase"))){reviewFixes();}else if("tight-spacing".equals(args.getString("phase"))){tightSpacing();}else if("spacing-range".equals(args.getString("phase"))){spacingRange();}else{if(!"offline".equals(args.getString("phase")))cacheAndMigration();baseline();if(!"offline".equals(args.getString("phase"))){turns();spacing();timeAndWarm();}else{assertTrue(!reader.surface.frame.layout.commentParagraphs.isEmpty(),"offline first frame bubbles");record("offline_cached_first_frame",true);shot("offline-cached-bubbles");}}result.putString("stream","PASS "+checks.length()+" reading controls checks\n");}catch(Throwable e){failure=e;try{record("failure_state",reader==null?"no reader":"busy="+reader.busy+", page="+(reader.surface.frame==null?-1:reader.surface.frame.pageIndex)+", focus="+reader.hasWindowFocus()+", keys="+reader.readingKeys);shot("failure");}catch(Exception ignored){}result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));}finally{restore();}try{try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(output,"results.json")),"UTF-8")){w.write(new JSONObject().put("success",failure==null).put("checks",checks).put("failure",failure==null?JSONObject.NULL:android.util.Log.getStackTraceString(failure)).toString(2));}}catch(Exception e){result.putString("stream",e.toString());}finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}

